56	// Efficiently dequantize an int32 value into a full B-fragment of 4 fp16 values.
57	// We mostly follow the strategy in the link below, with some small changes:
58	// https://github.com/NVIDIA/FasterTransformer/blob/main/src/fastertransformer/cutlass_extensions/include/cutlass_extensions/interleaved_numeric_conversion.h
59	__device__ inline FragA lop3_dequant(int q) {
60	    const int LO = 0x000f000f;
61	    const int HI = 0x00f000f0;
62	    const int EX = 0x64006400;
63	
64	    // Shift right by 8 to now consider elt_45 and elt_67. Issue first to hide RAW dependency if we issue
65	    // immediately before required.
66	    const uint32_t top_i4s = q >> 8;
67	
68	    // Guarantee that the `(a & b) | c` operations are LOP3s.
69	    int lo_1 = lop3<(0xf0 & 0xcc) | 0xaa>(q, LO, EX);        // 0,4
70	    int hi_1 = lop3<(0xf0 & 0xcc) | 0xaa>(q, HI, EX);        // 1,5
71	    int lo_2 = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, LO, EX);  // 2,6
72	    int hi_2 = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, HI, EX);  // 3,7
73	
74	    // We want signed int4 outputs, hence we fuse the `-8` symmetric zero point directly into `SUB` and `ADD`.
75	    const int SUB = 0x64006400; // 0x64086408
76	    const int MUL = 0x2c002c00; // {1/16, 1/16}
77	    const int ADD = 0xd400d400; // 0xd480d480
78	
79	    FragA frag_a;
80	    frag_a[0] = __hsub2(
81	        *reinterpret_cast<half2*>(&lo_1),
82	        *reinterpret_cast<const half2*>(&SUB)
83	    ); // 0,4
84	    frag_a[1] = __hfma2(
85	        *reinterpret_cast<half2*>(&hi_1),
86	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
87	    ); // 1,5
88	    frag_a[2] = __hsub2(
89	        *reinterpret_cast<half2*>(&lo_2),
90	        *reinterpret_cast<const half2*>(&SUB)
91	    ); // 2,6
92	    frag_a[3] = __hfma2(
93	        *reinterpret_cast<half2*>(&hi_2),
94	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
95	    ); // 3,7
96	
97	    return frag_a;
98	}
