101	// Efficiently dequantize an int32 value into a full B-fragment of 4 fp16 values.
102	// We mostly follow the strategy in the link below, with some small changes:
103	// https://github.com/NVIDIA/FasterTransformer/blob/main/src/fastertransformer/cutlass_extensions/include/cutlass_extensions/interleaved_numeric_conversion.h
104	__device__ inline FragB lop3_dequant_2bit(int q) {
105	    const int LO = 0x00030003;
106	    const int HI = 0x00300030;
107	    const int EX = 0x64006400;
108	
109	    // Shift right by 8 to now consider elt_45 and elt_67. Issue first to hide RAW dependency if we issue
110	    // immediately before required.
111	    const uint32_t top_i4s = q >> 8;
112	
113	    // Guarantee that the `(a & b) | c` operations are LOP3s.
114	    int lo_1_a = lop3<(0xf0 & 0xcc) | 0xaa>(q, LO, EX);            // 0,8
115	    int lo_1_b = lop3<(0xf0 & 0xcc) | 0xaa>(q >> 2, LO, EX);       // 1,9
116	    int hi_1_a = lop3<(0xf0 & 0xcc) | 0xaa>(q, HI, EX);            // 2,10
117	    int hi_1_b = lop3<(0xf0 & 0xcc) | 0xaa>(q >> 2, HI, EX);       // 3,11
118	    int lo_2_a = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, LO, EX);      // 4,12
119	    int lo_2_b = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s >> 2, LO, EX); // 5,13
120	    int hi_2_a = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, HI, EX);      // 6,14
121	    int hi_2_b = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s >> 2, HI, EX); // 7,15
122	
123	
124	    // int hi_2 = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, HI, EX);  // 3,7
125	
126	    // We want signed int4 outputs, hence we fuse the `-8` symmetric zero point directly into `SUB` and `ADD`.
127	    const int SUB = 0x64006400; // {1024, 1024} 0x64086408 
128	    const int MUL = 0x2c002c00; // {1/16, 1/16}
129	    const int ADD = 0xd400d400; // {-64, -64} 0xd480d480 
130	
131	    FragB frag_b;
132	    frag_b[0] = __hsub2(
133	        *reinterpret_cast<half2*>(&lo_1_a),
134	        *reinterpret_cast<const half2*>(&SUB)
135	    ); // 0,8
136	    frag_b[1] = __hsub2(
137	        *reinterpret_cast<half2*>(&lo_1_b),
138	        *reinterpret_cast<const half2*>(&SUB)
139	    ); // 1,9
140	    frag_b[2] = __hfma2(
141	        *reinterpret_cast<half2*>(&hi_1_a),
142	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
143	    ); // 2,10
144	    frag_b[3] = __hfma2(
145	        *reinterpret_cast<half2*>(&hi_1_b),
146	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
147	    ); // 3,11
148	    frag_b[4] = __hsub2(
149	        *reinterpret_cast<half2*>(&lo_2_a),
150	        *reinterpret_cast<const half2*>(&SUB)
151	    ); // 4,12
152	    frag_b[5] = __hsub2(
153	        *reinterpret_cast<half2*>(&lo_2_b),
154	        *reinterpret_cast<const half2*>(&SUB)
155	    ); // 5,13
156	    frag_b[6] = __hfma2(
157	        *reinterpret_cast<half2*>(&hi_2_a),
158	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
159	    ); // 6,14
160	    frag_b[7] = __hfma2(
161	        *reinterpret_cast<half2*>(&hi_2_b),
162	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
163	    ); // 7,15
164	
165	    return frag_b;
166	}
