253	template<class SourceEngine, class SourceLayout,  
254	         class TargetEngine, class TargetLayout,
255	         class ScaleEngine,  class ScaleLayout,
256	         class ZeroEngine,   class ZeroLayout>
257	struct dequant_kc_vt<2, SourceEngine, SourceLayout, TargetEngine, TargetLayout, ScaleEngine, ScaleLayout, ZeroEngine, ZeroLayout> {
258	    static constexpr int num_bits = 2;
259	    CUTE_DEVICE static 
260	    void apply(cute::Tensor<SourceEngine   , SourceLayout   > const& source,  
261	               cute::Tensor<TargetEngine   , TargetLayout   > const& target,
262	               cute::Tensor<ScaleEngine    , ScaleLayout    > const& scales,
263	               cute::Tensor<ZeroEngine     , ZeroLayout     > const& zeros,
264	               const int num_params) {
265	        using TQ  = cute::uint16_t;
266	        using TQ2 = cute::uint32_t;
267	        using T   = typename TargetEngine::value_type;
268	        using T2  = __half2;
269	        const int num_params_ = num_params / 2;                // TODO: only for g128
270	        const int pack_num    = 4 / num_params_;               // TODO: check 4
271	        
272	        // vectorize the source and target
273	        auto scales_vec  = cute::recast<T2>(scales);
274	        auto zeros_vec   = cute::recast<T2>(zeros);
275	        auto source_vec  = cute::recast<TQ2>(source);
276	        auto target_vec  = cute::recast<T2>(target);
277	
278	        const int channel_stride = size<0>(source_vec);
279	        
280	        CUTE_UNROLL
281	        for (int i = 0; i < cute::size<0>(source_vec); ++i) {
282	
283	            CUTE_UNROLL
284	            for (int p = 0; p < cute::size<1>(source_vec); ++p) {
285	                auto src_crd = cute::make_coord(i, p);
286	                auto src_raw = source_vec(src_crd);
287	                auto src_val = lop3_dequant_2bit(src_raw);
288	
289	                CUTE_UNROLL
290	                for (int j = 0; j < size<1>(target_vec); ++j) {
291	                    target_vec(i, j) = __hfma2(src_val[j], scales_vec(i + j / pack_num * channel_stride), zeros_vec(i + j / pack_num * channel_stride));
292	                }
293	
294	                // target_vec(i,0) = __hfma2(src_val[0], scales_vec(i), zeros_vec(i));
295	                // target_vec(i,1) = __hfma2(src_val[1], scales_vec(i + 1 / pack_num * channel_stride), zeros_vec(i + 1 / pack_num * channel_stride));
296	                // target_vec(i,2) = __hfma2(src_val[2], scales_vec(i + 2 / pack_num * channel_stride), zeros_vec(i + 2 / pack_num * channel_stride));
297	                // target_vec(i,3) = __hfma2(src_val[3], scales_vec(i + 3 / pack_num * channel_stride), zeros_vec(i + 3 / pack_num * channel_stride));
298	                // target_vec(i,4) = __hfma2(src_val[4], scales_vec(i + 4 / pack_num * channel_stride), zeros_vec(i + 4 / pack_num * channel_stride));
299	                // target_vec(i,5) = __hfma2(src_val[5], scales_vec(i + 5 / pack_num * channel_stride), zeros_vec(i + 5 / pack_num * channel_stride));
300	                // target_vec(i,6) = __hfma2(src_val[6], scales_vec(i + 6 / pack_num * channel_stride), zeros_vec(i + 6 / pack_num * channel_stride));
301	                // target_vec(i,7) = __hfma2(src_val[7], scales_vec(i + 7 / pack_num * channel_stride), zeros_vec(i + 7 / pack_num * channel_stride));
302	
303	                // target_vec(i,0) = __hfma2(src_val[0], scales_vec(0), zeros_vec(0));
304	                // target_vec(i,1) = __hfma2(src_val[1], scales_vec(0), zeros_vec(0));
305	                // target_vec(i,2) = __hfma2(src_val[2], scales_vec(0), zeros_vec(0));
306	                // target_vec(i,3) = __hfma2(src_val[3], scales_vec(0), zeros_vec(0));
307	                // target_vec(i,4) = __hfma2(src_val[4], scales_vec(0), zeros_vec(0));
308	                // target_vec(i,5) = __hfma2(src_val[5], scales_vec(0), zeros_vec(0));
309	                // target_vec(i,6) = __hfma2(src_val[6], scales_vec(0), zeros_vec(0));
310	                // target_vec(i,7) = __hfma2(src_val[7], scales_vec(0), zeros_vec(0));
311	
312	                // target_vec(i,0) = src_val[0];
313	                // target_vec(i,1) = src_val[1];
314	                // target_vec(i,2) = src_val[2];
315	                // target_vec(i,3) = src_val[3];
316	                // target_vec(i,4) = src_val[4];
317	                // target_vec(i,5) = src_val[5];
318	                // target_vec(i,6) = src_val[6];
319	                // target_vec(i,7) = src_val[7];
320	            }
321	        }
