325	template<class SourceEngine, class SourceLayout,  
326	         class TargetEngine, class TargetLayout,
327	         class ScaleEngine,  class ScaleLayout,
328	         class ZeroEngine,   class ZeroLayout>
329	struct dequant_kc_vt<4, SourceEngine, SourceLayout, TargetEngine, TargetLayout, ScaleEngine, ScaleLayout, ZeroEngine, ZeroLayout> {
330	    static constexpr int num_bits = 4;
331	    CUTE_DEVICE static 
332	    void apply(cute::Tensor<SourceEngine   ,SourceLayout   > const& source,  
333	               cute::Tensor<TargetEngine   ,TargetLayout   > const& target,
334	               cute::Tensor<ScaleEngine    ,ScaleLayout    > const& scales,
335	               cute::Tensor<ZeroEngine     ,ZeroLayout     > const& zeros,
336	               const int num_params) {
337	        using TQ  = cute::uint16_t;
338	        using TQ2 = cute::uint32_t;
339	        using T   = typename TargetEngine::value_type;
340	        using T2  = __half2;
341	        const int pack_num            = 4 / num_params;
342	        
343	        // vectorize the source and target
344	        auto scales_vec  = cute::recast<T2>(scales);
345	        auto zeros_vec   = cute::recast<T2>(zeros);
346	        auto source_vec  = cute::recast<TQ2>(source);
347	        auto target_vec  = cute::recast<T2>(target);
348	
349	        const int channel_stride = cute::size<0>(source_vec);
350	        const int scales_stride  = cute::size<0>(scales_vec);
351	
352	        CUTE_UNROLL
353	        for (int i = 0; i < cute::size<0>(source_vec); ++i)     // 2
354	        {
355	            CUTE_UNROLL
356	            for (int p = 0; p < cute::size<1>(source_vec); ++p) // 1
357	            {
358	                auto src_crd = cute::make_coord(i, p);
359	                auto src_raw = source_vec(src_crd);
360	                auto src_val = lop3_dequant(src_raw);
361	
362	                auto col_offset = p * num_bits;
363	
364	                auto tgt0_crd        = cute::make_coord(i, col_offset + 0);
365	                auto tgt1_crd        = cute::make_coord(i, col_offset + 1);
366	                auto tgt2_crd        = cute::make_coord(i, col_offset + 2);
367	                auto tgt3_crd        = cute::make_coord(i, col_offset + 3);
368	
369	                // TODO: hard code for now 2
370	                int params_crd = i;
371	
372	                target_vec(tgt0_crd) = __hfma2(src_val[0], scales_vec(params_crd + p * scales_stride), zeros_vec(params_crd + p * scales_stride));
373	                target_vec(tgt1_crd) = __hfma2(src_val[1], scales_vec(params_crd + 1 / pack_num * channel_stride + p * scales_stride), zeros_vec(params_crd + 1 / pack_num * channel_stride + p * scales_stride));
374	                target_vec(tgt2_crd) = __hfma2(src_val[2], scales_vec(params_crd + 2 / pack_num * channel_stride + p * scales_stride), zeros_vec(params_crd + 2 / pack_num * channel_stride + p * scales_stride));
375	                target_vec(tgt3_crd) = __hfma2(src_val[3], scales_vec(params_crd + 3 / pack_num * channel_stride + p * scales_stride), zeros_vec(params_crd + 3 / pack_num * channel_stride + p * scales_stride));
376	
377	                // target_vec(tgt0_crd) = src_val[0];
378	                // target_vec(tgt1_crd) = src_val[1];
379	                // target_vec(tgt2_crd) = src_val[2];
380	                // target_vec(tgt3_crd) = src_val[3];
381	            }
382	        }
383	    }
384	};
