403	template <class SourceEngine, class SourceLayout,  
404	          class TargetEngine, class TargetLayout,
405	          typename TensorParamsG1, typename TensorParamsG2>
406	CUTE_DEVICE  
407	void  
408	dequantize_Ktensor(  
409	    cute::Tensor<SourceEngine   , SourceLayout   > const& source,  
410	    cute::Tensor<TargetEngine   , TargetLayout   > & target,
411	    TensorParamsG1 & scales_k_g_vec,
412	    TensorParamsG2 & zeros_k_g_vec,
413	    int num_bits,
414	    int group_size,
415	    int ii
416	) {  
417	    using TQ  = cute::uint16_t;
418	    using TQ2 = cute::uint32_t;
419	    using T   = typename TargetEngine::value_type;
420	    using T2  = __half2;
421	
422	    static constexpr int kNumBits    = 4;
423	    const int num_params             = 128 / group_size;
424	    const int ki                     = size<2>(target) / num_params;
425	
426	    // vectorize the source and target
427	    auto scales_k_g  = cute::recast<T>(scales_k_g_vec);
428	    auto zeros_k_g   = cute::recast<T>(zeros_k_g_vec);
429	    auto source_vec  = cute::recast<TQ2>(source);
430	    auto target_vec  = cute::recast<T2>(target);
431	
432	    const int tile_j = size<2>(target) != size<2>(source) ? 2 : 1;
433	
434	    CUTE_UNROLL
435	    for (int i = 0; i < cute::size<0>(source_vec); ++i)
436	    {
437	        auto src_crd = cute::make_coord(0, 0, 0);
438	        for (int p = 0; p < tile_j; ++p) {
439	            src_crd = tile_j == 1 ? cute::make_coord(i, 0, ii) : cute::make_coord(i, 0, 8 * (ii / 4) + ii % 4 + p * 4);
440	            auto src_raw = source_vec(src_crd);
441	            auto src_val = lop3_dequant(src_raw);
442	
443	            auto col_offset = p * kNumBits;
444	
445	            auto tgt0_crd      = cute::make_coord(i, col_offset + 0, ii);
446	            auto tgt1_crd      = cute::make_coord(i, col_offset + 1, ii);
447	            auto tgt2_crd      = cute::make_coord(i, col_offset + 2, ii);
448	            auto tgt3_crd      = cute::make_coord(i, col_offset + 3, ii);
449	
