12	CUTE_DEVICE
13	void thread_reduce_(Tensor0 const& tensor, Tensor1& summary, Operator& op, const int num_params) {
14	    const int pack_num = size<1>(tensor) / num_params;
15	
16	    CUTE_UNROLL
17	    for (int mi = 0; mi < size<0>(summary); ++mi) {
18	        int col_start = (mi / 4) * pack_num;
19	        summary(mi) = tensor(mi % 4, col_start);
20	
21	        CUTE_UNROLL
22	        for (int ni = col_start; ni < col_start + pack_num; ++ni) {
23	            summary(mi) = op(summary(mi), tensor(mi % 4, ni));
24	        }
25	
26	    }
27	
28	}
