110	template<typename Tensor1, typename Tensor2, typename Tensor3, typename Tensor4, typename Tensor5>
111	struct qpack_kc_vt<2, Tensor1, Tensor2, Tensor3, Tensor4, Tensor5> {
112	    static constexpr int num_bits = 2;  // Add this line
113	    CUTE_DEVICE static 
114	    void apply(Tensor1 &src, Tensor2 &dst, Tensor3 &scales_k, Tensor4 &zeros_k, Tensor5 &reduce_tmp, const int num_params) {
115	        const float max_val      = float((1 << num_bits) - 1);
116	        const int pack_num       = 4 / (num_params / 2);                            // TODO: check 4
117	        const int num_params_2   = size<1>(src) == 4 ? num_params / 2 : num_params; // TODO: change name? seems hard code? 
118	        const int channel_stride = size<0>(src);
119	
120	        // Declare per-channel tensors
121	        using TensorChannel = decltype(make_fragment_like<float>(scales_k(_, 0)));
122	        TensorChannel channel_max, channel_min, channel_range, channel_scales_inv, channel_zeros;
123	
124	        CUTE_UNROLL
125	        for (int k = 0; k < size<2>(src); ++k) {
126	            // Perform per-channel max and min reductions
127	            quant::reduce_max(src(_, _, k), channel_max, reduce_tmp, num_params_2);
128	            quant::reduce_min(src(_, _, k), channel_min, reduce_tmp, num_params_2);
129	
130	            // Compute per-channel scale inverses and zeros
131	            CUTE_UNROLL
132	            for (int i = 0; i < size(channel_max); ++i) {
133	                float max_i = float(channel_max(i));
134	                float min_i = float(channel_min(i));
135	                float range = max_i - min_i;
136	                // Avoid division by zero
137	                float scale_inv = (range > 0.0f) ? (max_val / range) : 0.0f;
138	                channel_scales_inv(i) = scale_inv;
139	                channel_zeros(i) = min_i;
140	                // Store scales and zeros
141	                scales_k(i, k) = scale_inv == 0 ? 0.0f : 1.0f / scale_inv;  // Store actual scale
142	                zeros_k(i, k) = min_i;
143	            }
144	
145	            // Quantize and pack the tensor
146	            CUTE_UNROLL
147	            for (int i = 0; i < size<0>(src); ++i) {
148	
149	                CUTE_UNROLL
150	                for (int jj = 0; jj < size<1>(src); jj += 8) {
151	                    // float val0 = float(src(i, jj,     k));
152	                    // float val1 = float(src(i, jj + 1, k));
153	                    // float val2 = float(src(i, jj + 2, k));
154	                    // float val3 = float(src(i, jj + 3, k));
155	                    // float val4 = float(src(i, jj + 4, k));
156	                    // float val5 = float(src(i, jj + 5, k));
157	                    // float val6 = float(src(i, jj + 6, k));
158	                    // float val7 = float(src(i, jj + 7, k));
159	
160	                    // Load 4 values and convert to float
161	                    float val0 = float(src(i, jj,     k)) - channel_zeros(i + (jj    ) / pack_num * channel_stride);
162	                    float val1 = float(src(i, jj + 1, k)) - channel_zeros(i + (jj + 1) / pack_num * channel_stride);
163	                    float val2 = float(src(i, jj + 2, k)) - channel_zeros(i + (jj + 2) / pack_num * channel_stride);
164	                    float val3 = float(src(i, jj + 3, k)) - channel_zeros(i + (jj + 3) / pack_num * channel_stride);
165	                    float val4 = float(src(i, jj + 4, k)) - channel_zeros(i + (jj + 4) / pack_num * channel_stride);
166	                    float val5 = float(src(i, jj + 5, k)) - channel_zeros(i + (jj + 5) / pack_num * channel_stride);
167	                    float val6 = float(src(i, jj + 6, k)) - channel_zeros(i + (jj + 6) / pack_num * channel_stride);
168	                    float val7 = float(src(i, jj + 7, k)) - channel_zeros(i + (jj + 7) / pack_num * channel_stride);
169	
170	                    // Apply scale inverses
171	                    val0 *= channel_scales_inv(i + (jj    ) / pack_num * channel_stride);
172	                    val1 *= channel_scales_inv(i + (jj + 1) / pack_num * channel_stride);
173	                    val2 *= channel_scales_inv(i + (jj + 2) / pack_num * channel_stride);
174	                    val3 *= channel_scales_inv(i + (jj + 3) / pack_num * channel_stride);
175	                    val4 *= channel_scales_inv(i + (jj + 4) / pack_num * channel_stride);
176	                    val5 *= channel_scales_inv(i + (jj + 5) / pack_num * channel_stride);
177	                    val6 *= channel_scales_inv(i + (jj + 6) / pack_num * channel_stride);
178	                    val7 *= channel_scales_inv(i + (jj + 7) / pack_num * channel_stride);
179	
180	                    // Round and clamp the values
181	                    val0 = fminf(fmaxf(roundf(val0), 0.0f), max_val);
182	                    val1 = fminf(fmaxf(roundf(val1), 0.0f), max_val);
183	                    val2 = fminf(fmaxf(roundf(val2), 0.0f), max_val);
184	                    val3 = fminf(fmaxf(roundf(val3), 0.0f), max_val);
185	                    val4 = fminf(fmaxf(roundf(val4), 0.0f), max_val);
186	                    val5 = fminf(fmaxf(roundf(val5), 0.0f), max_val);
187	                    val6 = fminf(fmaxf(roundf(val6), 0.0f), max_val);
188	                    val7 = fminf(fmaxf(roundf(val7), 0.0f), max_val);
189	
190	                    // Pack 8 values (2-bit each) into a 16-bit integer
191	                    uint16_t packed = 0;
192	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val7)) & 0x3);  // 2 bits
193	                    packed <<= 2;
194	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val6)) & 0x3);
195	                    packed <<= 2;
196	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val5)) & 0x3);
197	                    packed <<= 2;
198	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val4)) & 0x3);
199	                    packed <<= 2;
200	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val3)) & 0x3);
201	                    packed <<= 2;
202	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val2)) & 0x3);
203	                    packed <<= 2;
204	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val1)) & 0x3);
205	                    packed <<= 2;
206	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val0)) & 0x3);
207	
208	                    // Store the packed value
209	                    dst(i, jj / 8, k) = packed;
210	                }
211	            }
212	        }
213	
214	    }
215	
216	
217	};
