    // // clear(tZeros_k_h2_g);

    // // clear(tScales_v_h2);
    // // clear(tZeros_v_h2);

    // // CUTE_UNROLL
    // // for (int i = 0; i < size<1>(tScales_v_h2); ++i) {
    // //     CUTE_UNROLL
